#!/usr/bin/env python3
# P-B19《最小必要维度 MRD》· r 梯 × 四舱 (判据先冻: PREREG_PB19_mrd.md)
# 读数四件/每训: final_loss / 尾四分能量比 ε(r) / 与前一 r 档的 V-A 嵌套重叠 / 细粗两分离度
# 修正注 (在册诚实): PREREG 原文 ε=E(超出k90)/E 与 k90 定义自斥 (恒 10%), 铸卷时改为"每模块底四分之一方向能量占比", 判值 5% 不动。
import os, json, time, base64, hashlib, copy
import numpy as np, torch
os.system("python -m pip uninstall -y -q torchao 2>/dev/null")
from transformers import AutoTokenizer, AutoModelForCausalLM
from peft import LoraConfig, get_peft_model, TaskType

SHA = "50db4ac9573b1190"
PACK = json.loads(base64.b64decode("").decode())
assert hashlib.sha256(json.dumps(PACK, ensure_ascii=False, sort_keys=True).encode()).hexdigest()[:16] == SHA, "pack drift"
MOUNT = "/kaggle/input/models/qwen-lm/qwen2.5/transformers/0.5b-instruct/1"
dev = "cuda"; OUT = "/kaggle/working"
RS = PACK["rs"]; EPOCHS = 6; HP = dict(lr=1e-4, accum=4, seed=13)
torch.manual_seed(HP["seed"]); np.random.seed(HP["seed"])
tok = AutoTokenizer.from_pretrained(MOUNT)
base_model = AutoModelForCausalLM.from_pretrained(MOUNT, dtype=torch.float16)  # CPU 母版, 每训深拷贝防改装

def enc_pair(u, a):
    msgs = [{"role":"user","content":u},{"role":"assistant","content":a}]
    pre = tok.apply_chat_template(msgs[:1]+[{"role":"assistant","content":""}], tokenize=False, add_generation_prompt=True)
    full = tok.apply_chat_template(msgs, tokenize=False, add_generation_prompt=False)
    fi = tok(full, add_special_tokens=False)["input_ids"]; pi = tok(pre, add_special_tokens=False)["input_ids"]
    return fi, [-100]*len(pi) + fi[len(pi):]
def collate(fs):
    L = max(len(f[0]) for f in fs); pad = tok.pad_token_id if tok.pad_token_id is not None else tok.eos_token_id
    ids = torch.tensor([i + [pad]*(L-len(i)) for i,_ in fs]); lab = torch.tensor([l + [-100]*(L-len(l)) for _,l in fs])
    at = torch.tensor([[1]*len(i)+[0]*(L-len(i)) for i,_ in fs])
    return ids.to(dev), lab.to(dev), at.to(dev)
def nll(text):
    e = tok(text, add_special_tokens=False, return_tensors="pt").to(dev)
    with torch.no_grad(): return float(m(**e, labels=e["input_ids"]).loss)

def train_arm(corps, r):
    global m
    global m
    m = None; torch.cuda.empty_cache()
    m = get_peft_model(copy.deepcopy(base_model), LoraConfig(task_type=TaskType.CAUSAL_LM, r=r, lora_alpha=2*r,
        lora_dropout=0.05, bias="none",
        target_modules=["q_proj","k_proj","v_proj","o_proj","gate_proj","up_proj","down_proj"]))
    m = m.to(dev); m.train()
    pairs = []
    for line in corps:
        o = json.loads(line); mm = o["messages"]; pairs.append(enc_pair(mm[0]["content"], mm[1]["content"]))
    opt = torch.optim.AdamW([p for p in m.parameters() if p.requires_grad], lr=HP["lr"])
    t0 = time.time(); last = 0.0
    for ep in range(1, EPOCHS+1):
        perm = np.random.permutation(len(pairs)); tot = 0.0; opt.zero_grad()
        for si, ix in enumerate(perm, 1):
            fi, la = pairs[int(ix)]
            x, y, a = collate([(fi, la)])
            loss = m(input_ids=x, attention_mask=a, labels=y).loss / HP["accum"]
            loss.backward(); tot += float(loss)*HP["accum"]
            if si % HP["accum"] == 0 or si == len(perm): opt.step(); opt.zero_grad()
        last = tot/len(perm)
    return last, round(time.time()-t0, 0)

def measure(r, cards, coarse):
    """四读数: 尾四分能量比 / 弦数 k90 / 细档分离 / 粗档分离; 并导出每模块 A 阵 V 供嵌套角。"""
    Vs = {}; ebot = []; k90s = []
    sd = {n: p.detach().cpu().float().numpy() for n, p in m.named_parameters() if ".lora_" in n}
    groups = {}
    for n, v in sd.items():
        b = n.split(".lora_")[0]; kind = n.split(".lora_")[1][0]
        groups.setdefault(b, {})[kind] = v
    for b, d in groups.items():
        U, s, Vt = np.linalg.svd(d["B"] @ d["A"], full_matrices=False)
        e = s**2; E = float(e.sum())
        if E <= 0: continue
        q = max(1, len(s)//4); ebot.append(float(np.sort(e)[:q].sum()/E))
        cs = np.cumsum(e); k90s.append(int(np.searchsorted(cs, 0.9*E)+1))
        Vs[b] = Vt[:min(len(s), max(k90s))]
    fine = float(np.mean([abs(nll(a)-nll(b)) for a, b in cards]))
    coarse_sep = float(np.mean([abs(nll(a)-nll(b)) for a, b in coarse]))
    return dict(tail_quart_energy=round(float(np.mean(ebot)), 4), k90_mean=round(float(np.mean(k90s)), 1),
                fine_sep=round(fine, 4), coarse_sep=round(coarse_sep, 4)), Vs

def nest(Va, Vb):
    """相邻 r 档 top-k 子空间嵌套重叠 (V-A Frobenius, 与 PB16 同器)。"""
    vals = []
    for b in Va:
        if b not in Vb: continue
        k = min(Va[b].shape[0], Vb[b].shape[0])
        if k == 0: continue
        vals.append(float(np.linalg.norm(Va[b][:k] @ Vb[b][:k].T, "fro") / np.sqrt(k)))
    return round(float(np.mean(vals)), 4) if vals else None

REPORT = dict(case="P-B19", pack_sha=SHA, rs=RS, epochs=EPOCHS, hp=HP,
              note="ε 定义修正见头注; 保存档 r∈{4,16,64}", runs=[])
def flush(tag):
    REPORT["_meta"] = dict(stage=tag, _selfcheck="pb19_ok" if tag == "final" else "wip", t=time.strftime("%H:%M:%S"))
    json.dump(REPORT, open(f"{OUT}/report_pb19.json", "w"), ensure_ascii=False)
    print("REPORT_LINE::" + base64.b64encode(json.dumps(REPORT, ensure_ascii=False).encode()).decode()[:3800], flush=True)

T0 = time.time()
for dname in ["D1_nba", "D2_gen", "D3_alpha", "D4_spring"]:
    prev_V = None
    for r in RS:
        torch.manual_seed(HP["seed"]); np.random.seed(HP["seed"])
        loss, tsec = train_arm(PACK["corps"][dname], r)
        mt, Vs = measure(r, PACK["cards"][dname], PACK["coarse"][dname])
        row = dict(data=dname, r=r, loss=round(loss, 4), secs=tsec, **mt)
        if prev_V is not None: row["nest_prev"] = nest(prev_V, Vs)
        prev_V = Vs
        if r in (4, 16, 64):
            ck = f"{OUT}/adapters_{dname}_r{r}"; m.save_pretrained(ck)
            sz = sum(os.path.getsize(f"{ck}/{f}") for f in os.listdir(ck) if f.endswith(".safetensors"))
            assert sz > 1024, "0 字节/空壳 adapter (律二)"
            row["adapter_bytes"] = sz
        REPORT["runs"].append(row); flush(f"{dname}/r{r}")
        print(f"== {dname} r={r}: loss {loss:.3f} tailE {mt['tail_quart_energy']} k90 {mt['k90_mean']} fine {mt['fine_sep']} coarse {mt['coarse_sep']} nest {row.get('nest_prev')} ({(time.time()-T0)/60:.0f}min)", flush=True)
flush("final")
print("DONE PB19", flush=True)
